DEFAULT_DEPARTMENT_ROLES = (('Leader', True), ('Secretary', False), ('Treasurer', False))


def seed_departments_and_backfill(apps, schema_editor):
    """Seed the ten departments and carry over whoever held an office.

    Eldership, Clerkship and Deaconate come along as departments — the
    church itself does not: its church-wide roles return to User Management.
    The 0139 areas are read for leadership backfill: a named office keeps
    its name as the department role (Eldership's First Elder, Deaconate's
    Head Deacon), a generic Leader keeps "Leader", and an Assistant office
    becomes an assistant row on the same role. No one loses their post in
    the move.
    """
    Department = apps.get_model('members', 'Department')
    DepartmentRole = apps.get_model('members', 'DepartmentRole')
    DepartmentAssignment = apps.get_model('members', 'DepartmentAssignment')
    LeadershipArea = apps.get_model('members', 'LeadershipArea')
    AreaRole = apps.get_model('members', 'AreaRole')

    departments = {}
