    for code, name, sort in SEED_DEPARTMENTS:
        department, _ = Department.objects.get_or_create(
            code=code,
            defaults={'name': name, 'sort_order': sort},
        )
        departments[code] = department
        template = SEED_DEPARTMENT_ROLES.get(code, DEFAULT_DEPARTMENT_ROLES)
        roles_by_department[code] = {}
        for index, (role_name, assistant) in enumerate(template):
            role, _ = DepartmentRole.objects.get_or_create(
                department=department, name=role_name,
                defaults={'has_assistant': assistant, 'sort_order': index},
            )
            roles_by_department[code][role_name.lower()] = role

    def role_for(department_code, title):
        """The department role an office title lands in, creating it if new."""
        registry = roles_by_department[department_code]
        key = title.strip().lower()
        if key not in registry:
            role, _ = DepartmentRole.objects.get_or_create(
                department=departments[department_code], name=title.strip(),
                defaults={'sort_order': 100, 'is_custom': True},
            )
            registry[key] = role
        return registry[key]

    for area in LeadershipArea.objects.all():
        department = departments.get(area.code)
        if department is None:
            continue  # The church: its offices were church-wide roles.
        for position in AreaRole.objects.filter(area=area).order_by('position_order', 'id'):
            if not position.holder_id:
                continue
            title = position.title.strip()
            if title.lower() == 'assistant':
                # The generic assistant office becomes an assistant row on
                # the department's assistant-capable base role (Leader).
                base = next(
                    (r for r in roles_by_department[area.code].values() if r.has_assistant),
                    None,
                )
